		el := snap.EffectiveLoad()
		if el < minLoad {
			minLoad = el
		}
		if el > maxLoad {
			maxLoad = el
		}
	}

	// Under high load, shift weight toward load-balance (index 1)
	w := make([]float64, len(ws.weights))
