	}

	// Light post-scoring: penalize near-full KV and reward cache hits
	for _, snap := range snapshots {
		if snap.KVUtilization > 0.9 {
			scores[snap.ID] *= 0.5
		} else if snap.KVUtilization > 0.8 {
			scores[snap.ID] *= 0.8
		}
		scores[snap.ID] *= (1.0 + 0.1*snap.CacheHitRate)
	}

	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
